,p_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_css_classes=>'segment-summary-report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    REQUESTING_SEGMENT,',
'    REQUESTING_LOB,',
'',
'    COUNT(*) AS TOTAL_REQUESTS,',
'',
'    SUM(',
'        CASE',
'            WHEN UPPER(APPROVAL_STATUS) = ''APPROVED''',
'            THEN 1',
'            ELSE 0',
'        END',
'    ) AS APPROVED,',
'',
'    SUM(',
'        CASE',
'            WHEN UPPER(APPROVAL_STATUS) = ''PENDING''',
'            THEN 1',
'            ELSE 0',
'        END',
'    ) AS PENDING,',
'',
'    SUM(',
'        CASE',
'            WHEN UPPER(APPROVAL_STATUS) = ''REJECTED''',
'            THEN 1',
'            ELSE 0',
'        END',
'    ) AS REJECTED',
'',
'FROM INVESTMENTS',
'',
'GROUP BY',
'    REQUESTING_SEGMENT,',
'    REQUESTING_LOB',
'',
'UNION ALL',
'',
'SELECT',
'    ''TOTAL'',',
'    NULL,',
'',
'    COUNT(*) AS TOTAL_REQUESTS,',
'',
'    SUM(',
'        CASE',
'            WHEN UPPER(APPROVAL_STATUS) = ''APPROVED''',
'            THEN 1',
'            ELSE 0',
'        END',
'    ) AS APPROVED,',
'',
'    SUM(',
'        CASE',
'            WHEN UPPER(APPROVAL_STATUS) = ''PENDING''',
'            THEN 1',
'            ELSE 0',
'        END',
'    ) AS PENDING,',
'',
'    SUM(',
'        CASE',
'            WHEN UPPER(APPROVAL_STATUS) = ''REJECTED''',
'            THEN 1',
'            ELSE 0',
'        END',
'    ) AS REJECTED',
'',
'FROM INVESTMENTS;'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
