wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(39504176086804459406)
,p_name=>'Type wise Report'
,p_static_id=>'type-wise-report'
,p_title=>'Type wise Report'
,p_parent_plug_id=>wwv_flow_imp.id(39504177296908459418)
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_css_classes=>'type-summary-report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH initiative_type_lov AS',
'(',
'    SELECT',
'        CAST(return_value AS VARCHAR2(4000))  AS return_value,',
'        CAST(display_value AS VARCHAR2(4000)) AS display_value,',
'        display_sequence',
'    FROM apex_application_lov_entries',
'    WHERE application_id = :APP_ID',
'      AND list_of_values_name = ''INITIATIVE_TYPE_LOV''',
'),',
'strategic_priority_lov AS',
'(',
'    SELECT',
'        CAST(return_value AS VARCHAR2(4000))  AS return_value,',
'        CAST(display_value AS VARCHAR2(4000)) AS display_value,',
'        display_sequence',
'    FROM apex_application_lov_entries',
'    WHERE application_id = :APP_ID',
'      AND list_of_values_name = ''STRATEGIC_PRIORITY_LOV''',
'),',
'type_rows AS',
'(',
'    SELECT',
'        t.display_sequence * 100 AS sort_order,',
'',
'        CAST(',
'            t.display_value',
'            AS VARCHAR2(4000)',
'        ) AS initiative_type,',
'',
'        COUNT(i.investment_id) AS total_requests,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(i.approval_status) = ''APPROVED''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS approved,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(i.approval_status) = ''PENDING''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS pending,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(i.approval_status) = ''REJECTED''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS rejected',
'',
'    FROM initiative_type_lov t',
'',
'    LEFT JOIN investments i',
'        ON i.initiative_type = t.return_value',
'',
'    GROUP BY',
'        t.display_sequence,',
'        t.display_value',
'),',
'priority_rows AS',
'(',
'    SELECT',
'        NVL(',
'            (',
'                SELECT display_sequence * 100',
'                FROM initiative_type_lov',
'                WHERE return_value = ''SP''',
'            ),',
'            300',
'        ) + p.display_sequence AS sort_order,',
'',
'        CAST(',
'            ''    '' || p.display_value',
'            AS VARCHAR2(4000)',
'        ) AS initiative_type,',
'',
'        COUNT(i.investment_id) AS total_requests,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(i.approval_status) = ''APPROVED''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS approved,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(i.approval_status) = ''PENDING''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS pending,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(i.approval_status) = ''REJECTED''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS rejected',
'',
'    FROM strategic_priority_lov p',
'',
'    LEFT JOIN investments i',
'        ON i.initiative_type = ''SP''',
'       AND i.strategic_priority = p.return_value',
'',
'    GROUP BY',
'        p.display_sequence,',
'        p.display_value',
'),',
'total_row AS',
'(',
'    SELECT',
'        999999 AS sort_order,',
'',
'        CAST(',
'            ''TOTAL''',
'            AS VARCHAR2(4000)',
'        ) AS initiative_type,',
'',
'        COUNT(*) AS total_requests,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(approval_status) = ''APPROVED''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS approved,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(approval_status) = ''PENDING''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS pending,',
'',
'        SUM(',
'            CASE',
'                WHEN UPPER(approval_status) = ''REJECTED''',
'                THEN 1',
'                ELSE 0',
'            END',
'        ) AS rejected',
'',
'    FROM investments',
')',
'SELECT',
'    initiative_type,',
'    total_requests,',
'    approved,',
'    pending,',
'    rejected,',
'    sort_order',
'FROM',
'(',
'    SELECT',
'        initiative_type,',
'        total_requests,',
'        approved,',
'        pending,',
'        rejected,',
'        sort_order',
'    FROM type_rows',
'',
'    UNION ALL',
'',
'    SELECT',
'        initiative_type,',
'        total_requests,',
'        approved,',
'        pending,',
'        rejected,',
'        sort_order',
'    FROM priority_rows',
'',
'    UNION ALL',
'',
'    SELECT',
'        initiative_type,',
'        total_requests,',
'        approved,',
'        pending,',
'        rejected,',
'        sort_order',
'    FROM total_row',
')',
'ORDER BY sort_order'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260919162535Z')
,p_updated_on=>wwv_flow_imp.dz('20260919181249Z')
,p_created_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
,p_updated_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
);
