wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(40730292821774990225)
,p_event_id=>wwv_flow_imp.id(40730292797670990224)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_name=>'total_true'
,p_static_id=>'true-action'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'COLUMN'
,p_affected_elements=>'TOTAL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var triggeringRegion = this.triggeringElement;',
    '',
    'setTimeout(function () {',
    '',
    '    var ig$ = $(triggeringRegion).find(".a-IG");',
    '',
    '    if (!ig$.length) {',
    '        console.error("Funding Interactive Grid was not found.");',
    '        return;',
    '    }',
    '',
    '    var gridView = ig$.interactiveGrid("getViews", "grid");',
    '    var model = gridView.model;',
    '',
    '    model.forEach(function (record) {',
    '',
    '        function getNumber(columnName) {',
    '            var value = model.getValue(record, columnName);',
    '',
    '            if (',
    '                value === null ||',
    '                value === undefined ||',
    '                value === ""',
    '            ) {',
    '                return 0;',
    '            }',
    '',
    '            return parseFloat(',
    '                String(value).replace(/,/g, "")',
    '            ) || 0;',
    '        }',
    '',
    '        var fy1 = getNumber("FY1");',
    '        var fy2 = getNumber("FY2");',
    '        var fy3 = getNumber("FY3");',
    '        var fy4 = getNumber("FY4");',
    '        var fy5 = getNumber("FY5");',
    '        var fy6 = getNumber("FY6");',
    '        var fy7 = getNumber("FY7");',
    '',
    '        var total =',
    '            fy1 +',
    '            fy2 +',
    '            fy3 +',
    '            fy4 +',
    '            fy5 +',
    '            fy6 +',
    '            fy7;',
    '',
    '        /* Display calculated total in the grid */',
    '        model.setValue(',
    '            record,',
    '            "TOTAL",',
    '            total.toFixed(2)',
    '        );',
    '',
    '        /* Copy grid values into Page 5 hidden items */',
    '        $s("P5_FY1", fy1);',
    '        $s("P5_FY2", fy2);',
    '        $s("P5_FY3", fy3);',
    '        $s("P5_FY4", fy4);',
    '        $s("P5_FY5", fy5);',
    '        $s("P5_FY6", fy6);',
    '        $s("P5_FY7", fy7);',
    '    });',
    '',
    '}, 1);')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260924081252Z')
,p_updated_on=>wwv_flow_imp.dz('20261001161616Z')
,p_created_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
,p_updated_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
);
