wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(36899622072430916514)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create'
,p_static_id=>'create'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_investment_id        investments.investment_id%TYPE;',
'',
'    l_attachment_file      BLOB;',
'    l_attachment_file_name VARCHAR2(4000);',
'    l_attachment_mime_type VARCHAR2(255);',
'',
'BEGIN',
'',
'    /* -----------------------------------------',
'       Get attachment from temporary storage',
'       ----------------------------------------- */',
'',
'    IF :P5_ATTACHMENT_FILE IS NOT NULL THEN',
'',
'        SELECT',
'            blob_content,',
'            filename,',
'            mime_type',
'        INTO',
'            l_attachment_file,',
'            l_attachment_file_name,',
'            l_attachment_mime_type',
'        FROM apex_application_temp_files',
'        WHERE name = :P5_ATTACHMENT_FILE;',
'',
'    END IF;',
'',
'',
'    /* -----------------------------------------',
'       Create Investment',
'       ----------------------------------------- */',
'',
'    INSERT INTO investments',
'    (',
'        initiative,',
'        description,',
'        initiative_type,',
'        strategic_priority,',
'',
'        requesting_segment,',
'        requesting_lob,',
'        requesting_elt,',
'',
'        finance_contact,',
'        business_contact,',
'        funding_type,',
'',
'        leader_priority,',
'        tech_resource_required,',
'        closed_sales_impact,',
'        international_related,',
'        ius_eligible,',
'',
'        cba_applicable,',
'        prelim_roi,',
'',
'        decision_date_required,',
'        target_funding_start_date,',
'',
'        attachment_file,',
'        attachment_file_name,',
'        attachment_mime_type,',
'        attachment_updated_date,',
'',
'        fy27,',
'        fy28,',
'        fy29,',
'        fy30,',
'        fy31,',
'        fy32,',
'        fy33,',
'',
'        total_funding,',
'',
'        submission_status,',
'        approval_status,',
'',
'        created_by,',
'        created_date,',
'        updated_by,',
'        updated_date',
'    )',
'    VALUES',
'    (',
'        :P5_INITIATIVE,',
'        :P5_DESCRIPTION,',
'        :P5_INITIATIVE_TYPE,',
'',
'        CASE',
'            WHEN :P5_INITIATIVE_TYPE = ''SP''',
'            THEN :P5_STRATEGIC_PRIORITY',
'            ELSE NULL',
'        END,',
'',
'        :P5_REQUESTING_SEGMENT,',
'        :P5_REQUESTING_LOB,',
'        :P5_REQUESTING_ELT,',
'',
'        :P5_FINANCE_CONTACT,',
'        :P5_BUSINESS_CONTACT,',
'        :P5_FUNDING_TYPE,',
'',
'        :P5_LEADER_PRIORITY,',
'        :P5_TECH_RESOURCE_REQUIRED,',
'        :P5_CLOSED_SALES_IMPACT,',
'        :P5_INTERNATIONAL_RELATED,',
'        :P5_IUS_ELIGIBLE,',
'',
'        :P5_CBA_APPLICABLE,',
'        :P5_PRELIM_ROI,',
'',
'        :P5_DECISION_DATE_REQUIRED,',
'        :P5_TARGET_FUNDING_START_DATE,',
'',
'        l_attachment_file,',
'        l_attachment_file_name,',
'        l_attachment_mime_type,',
'',
'        CASE',
'            WHEN l_attachment_file IS NOT NULL',
'            THEN SYSDATE',
'            ELSE NULL',
'        END,',
'',
'        NVL(:P5_FY1, 0),',
'        NVL(:P5_FY2, 0),',
'        NVL(:P5_FY3, 0),',
'        NVL(:P5_FY4, 0),',
'        NVL(:P5_FY5, 0),',
'        NVL(:P5_FY6, 0),',
'        NVL(:P5_FY7, 0),',
'',
'        NVL(:P5_FY1, 0)',
'        + NVL(:P5_FY2, 0)',
'        + NVL(:P5_FY3, 0)',
'        + NVL(:P5_FY4, 0)',
'        + NVL(:P5_FY5, 0)',
'        + NVL(:P5_FY6, 0)',
'        + NVL(:P5_FY7, 0),',
'',
'        ''CREATED'',',
'        ''PENDING'',',
'',
'        :APP_USER,',
'        SYSDATE,',
'        :APP_USER,',
'        SYSDATE',
'    )',
'',
'    RETURNING investment_id',
'    INTO l_investment_id;',
'',
'',
'    /* -----------------------------------------',
'       Return generated values to Page 5',
'       ----------------------------------------- */',
'',
'    :P5_INVESTMENT_ID := l_investment_id;',
'    :P5_ATTACHMENT_FILE_NAME := l_attachment_file_name;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(75221105490274714527)
,p_process_success_message=>'done'
