,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_count NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(*)',
'    INTO l_count',
'    FROM FUNDING_REQUEST_STAGE',
'    WHERE APP_SESSION_ID = TO_CHAR(:APP_SESSION);',
'',
'    IF l_count = 0 THEN',
'',
'        INSERT INTO FUNDING_REQUEST_STAGE',
'        (',
'            APP_SESSION_ID,',
'            FY1,',
'            FY2,',
'            FY3,',
'            FY4,',
'            FY5,',
'            FY6,',
'            FY7,',
'            TOTAL',
'        )',
'        VALUES',
'        (',
'            TO_CHAR(:APP_SESSION),',
'            0,',
'            0,',
'            0,',
'            0,',
'            0,',
'            0,',
'            0,',
'            0',
'        );',
'',
'    END IF;',
'',
'END;'))
