,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    investment_id,',
'    initiative,',
'    initiative_type,',
'    strategic_priority,',
'    requesting_segment,',
'    requesting_lob,',
'    funding_type,',
'    approval_status,',
'',
'    -- CASE',
'    --     WHEN approval_status IS NULL',
'    --     THEN ''Not Reviewed''',
'    --     ELSE approval_status',
'    -- END AS approval_status,',
'',
'    prelim_roi,',
'',
'    fy27,',
'    fy28,',
'    fy29,',
'    fy30,',
'    fy31,',
'    fy32,',
'    fy33,',
'',
'    total_funding,',
'',
'    created_date',
'',
'FROM investments',
'',
'WHERE',
'    (',
'        :P6_SEGMENT IS NULL',
'        OR requesting_segment = :P6_SEGMENT',
'    )',
'',
'AND (',
'        :P6_REQUESTING_LOB IS NULL',
'        OR requesting_lob = :P6_REQUESTING_LOB',
'    )',
'',
'AND (',
'        :P6_INITIATIVE_TYPE IS NULL',
'        OR initiative_type = :P6_INITIATIVE_TYPE',
'    )',
'',
'AND (',
'        :P6_APPROVAL_STATUS IS NULL',
'        OR UPPER(approval_status)',
'           = UPPER(:P6_APPROVAL_STATUS)',
'    )',
'',
'AND (',
'        :P6_FUNDING_TYPE IS NULL',
'        OR funding_type = :P6_FUNDING_TYPE',
'    )',
'',
'AND (',
'        :P6_MINIMUM_FUNDING IS NULL',
'        OR total_funding >= :P6_MINIMUM_FUNDING',
'    )',
'',
'ORDER BY',
'    total_funding DESC'))
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
