wwv_flow_imp_page.create_page(
 p_id=>7
,p_name=>'Upload Document'
,p_alias=>'UPLOAD-DOCUMENT'
,p_step_title=>'Upload Document'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* =========================================',
'   EMPLOYEE BULK UPLOAD PAGE',
'   Simple Deep Mustard Theme',
'   ========================================= */',
'',
':root {',
'    --mustard: #b8860b;',
'    --mustard-dark: #8f6808;',
'    --cream: #fffaf0;',
'    --charcoal: #34312d;',
'    --border: #ddd8ce;',
'    --light-grey: #f7f7f5;',
'}',
'',
'',
'/* =========================================',
'   REGION CARDS',
'   ========================================= */',
'',
'.employee-upload,',
'.employee-preview {',
'    background: #ffffff !important;',
'    border: 1px solid var(--border) !important;',
'    border-radius: 10px !important;',
'    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.07) !important;',
'    overflow: hidden;',
'}',
'',
'.employee-preview {',
'    margin-top: 20px;',
'}',
'',
'',
'/* =========================================',
'   REGION HEADERS',
'   ========================================= */',
'',
'.employee-upload .t-Region-header,',
'.employee-preview .t-Region-header {',
'    background: var(--mustard) !important;',
'    border: none !important;',
'}',
'',
'.employee-upload .t-Region-title,',
'.employee-preview .t-Region-title {',
'    color: #ffffff !important;',
'    font-size: 18px !important;',
'    font-weight: 700 !important;',
'}',
'',
'',
'/* =========================================',
'   REGION BODY',
'   ========================================= */',
'',
'.employee-upload .t-Region-body {',
'    background: var(--cream) !important;',
'    padding: 20px !important;',
'}',
'',
'.employee-preview .t-Region-body {',
'    background: #ffffff !important;',
'    padding: 12px !important;',
'}',
'',
'',
'/* =========================================',
'   FORM LABEL',
'   ========================================= */',
'',
'.employee-upload .t-Form-label {',
'    color: var(--charcoal) !important;',
'    font-weight: 600 !important;',
'}',
'',
'',
'/* =========================================',
'   FILE UPLOAD',
'   ========================================= */',
'',
'.employee-upload input[type="file"] {',
'    background: #ffffff !important;',
'    border: 1px solid #d8d1c4 !important;',
'    border-radius: 6px !important;',
'}',
'',
'/* =========================================',
'   CLEAR PREVIEW BUTTON',
'   ========================================= */',
'',
'.employee-preview .t-Button {',
'    background: #ffffff !important;',
'    color: var(--mustard-dark) !important;',
'    border: 1px solid var(--mustard) !important;',
'    border-radius: 6px !important;',
'    font-weight: 600 !important;',
'}',
'',
'.employee-preview .t-Button:hover {',
'    background: var(--cream) !important;',
'}',
'',
'',
'/* =========================================',
'   EMPLOYEE REPORT TABLE',
'   ========================================= */',
'',
'.employee-preview table {',
'    width: 100%;',
'}',
'',
'',
'/* Table Header */',
'',
'.employee-preview table th {',
'    background: var(--charcoal) !important;',
'    color: #ffffff !important;',
'    font-weight: 600 !important;',
'    padding: 10px !important;',
'    border-color: #4d4943 !important;',
'}',
'',
'',
'/* Table Data */',
'',
'.employee-preview table td {',
'    color: #333333 !important;',
'    padding: 10px !important;',
'    border-color: #e9e5de !important;',
'}',
'',
'',
'/* Alternate Rows */',
'',
'.employee-preview table tbody tr:nth-child(even) td {',
'    background: var(--light-grey) !important;',
'}',
'',
'',
'/* Row Hover */',
'',
'.employee-preview table tbody tr:hover td {',
'    background: #fff4d6 !important;',
'}',
'',
'',
'/* Employee ID */',
'',
'.employee-preview table tbody td:first-child {',
'    color: var(--mustard-dark) !important;',
'    font-weight: 700 !important;',
'}',
'',
'.t-Button--hot {',
'    background-color: #996e2e !important;',
'    border-color: #7a5c2e !important;',
'    color: #ffffff !important;',
'}',
'',
'.t-Button--hot:hover {',
'    background-color: #7b5723 !important;',
'    border-color: #5d4523 !important;',
'}'))
,p_step_template=>4073832297226169690
