wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(42413296070634640704)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CLEAR_EMPLOYEE_PREVIEW'
,p_static_id=>'clear-employee-preview'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'',
'    /* Remove employee preview data */',
'    IF apex_collection.collection_exists(',
'        p_collection_name => ''EMPLOYEE_UPLOAD_PREVIEW''',
'    )',
'    THEN',
'',
'        apex_collection.delete_collection(',
'            p_collection_name => ''EMPLOYEE_UPLOAD_PREVIEW''',
'        );',
'',
'    END IF;',
'',
'    /* Hide preview region */',
'    :P7_SHOW_PREVIEW := NULL;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(42413295926242640703)
,p_internal_uid=>42413296070634640704
,p_created_on=>wwv_flow_imp.dz('20260929073818Z')
,p_updated_on=>wwv_flow_imp.dz('20260929073948Z')
,p_created_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
,p_updated_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(42183650185079463812)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PARSE_EMPLOYEE_FILE'
,p_static_id=>'parse-employee-file'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob          BLOB;',
'    l_clob          CLOB;',
'    l_filename      VARCHAR2(4000);',
'    l_mime_type     VARCHAR2(4000);',
'',
'    l_dest_offset   PLS_INTEGER := 1;',
'    l_src_offset    PLS_INTEGER := 1;',
'    l_lang_context  PLS_INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;',
'    l_warning       PLS_INTEGER;',
'',
'    l_lines         apex_t_varchar2;',
'    l_columns       apex_t_varchar2;',
'',
'    l_line          VARCHAR2(32767);',
'    l_row_count     PLS_INTEGER := 0;',
'BEGIN',
'    /*',
'      Confirm that a file was submitted.',
'    */',
'    IF :P7_UPLOAD_FILE IS NULL THEN',
'        raise_application_error(',
'            -20001,',
'            ''Please select an employee TXT file.''',
'        );',
'    END IF;',
'',
'',
'    /*',
'      Retrieve the uploaded TXT file from temporary storage.',
'      P7_UPLOAD_FILE contains the unique temporary NAME.',
'    */',
'    BEGIN',
'        SELECT blob_content,',
'               filename,',
'               mime_type',
'          INTO l_blob,',
'               l_filename,',
'               l_mime_type',
'          FROM apex_application_temp_files',
'         WHERE name = :P7_UPLOAD_FILE;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            raise_application_error(',
'                -20002,',
'                ''The uploaded file was not found in temporary storage.''',
'            );',
'    END;',
'',
'',
'    /*',
'      Convert uploaded BLOB into text.',
'    */',
'    DBMS_LOB.CREATETEMPORARY(',
'        lob_loc => l_clob,',
'        cache   => TRUE',
'    );',
'',
'    DBMS_LOB.CONVERTTOCLOB(',
'        dest_lob     => l_clob,',
'        src_blob     => l_blob,',
'        amount       => DBMS_LOB.LOBMAXSIZE,',
'        dest_offset  => l_dest_offset,',
'        src_offset   => l_src_offset,',
'        blob_csid    => NLS_CHARSET_ID(''AL32UTF8''),',
'        lang_context => l_lang_context,',
'        warning      => l_warning',
'    );',
'',
'',
'    /*',
'      Create or clear the employee preview collection.',
'    */',
'    IF apex_collection.collection_exists(',
'        p_collection_name => ''EMPLOYEE_UPLOAD_PREVIEW''',
'    ) THEN',
'        apex_collection.truncate_collection(',
'            p_collection_name => ''EMPLOYEE_UPLOAD_PREVIEW''',
'        );',
'    ELSE',
'        apex_collection.create_collection(',
'            p_collection_name => ''EMPLOYEE_UPLOAD_PREVIEW''',
'        );',
'    END IF;',
'',
'',
'    /*',
'      Split the TXT file into separate lines.',
'    */',
'    l_lines := apex_string.split(',
'        p_str => REPLACE(',
'                     DBMS_LOB.SUBSTR(',
'                         l_clob,',
'                         32767,',
'                         1',
'                     ),',
'                     CHR(13),',
'                     NULL',
'                 ),',
'        p_sep => CHR(10)',
'    );',
'',
'',
'    /*',
'      Start at row 2 because row 1 contains headings.',
'    */',
'    IF l_lines.COUNT >= 2 THEN',
'        FOR i IN 2 .. l_lines.COUNT LOOP',
'',
'            l_line := TRIM(l_lines(i));',
'',
'            IF l_line IS NOT NULL THEN',
'',
'                /*',
'                  Split the line by comma.',
'                */',
'                l_columns := apex_string.split(',
'                    p_str => l_line,',
'                    p_sep => '',''',
'                );',
'',
'                /*',
'                  Validate expected 10-column structure.',
'                */',
'                IF l_columns.COUNT = 10 THEN',
'',
'                    l_row_count := l_row_count + 1;',
'',
'                    apex_collection.add_member(',
'                        p_collection_name => ''EMPLOYEE_UPLOAD_PREVIEW'',',
'',
'                        p_c001 => TRIM(l_columns(1)),',
'                        p_c002 => TRIM(l_columns(2)),',
'                        p_c003 => TRIM(l_columns(3)),',
'                        p_c004 => TRIM(l_columns(4)),',
'                        p_c005 => TRIM(l_columns(5)),',
'                        p_c006 => TRIM(l_columns(6)),',
'                        p_c007 => TRIM(l_columns(7)),',
'                        p_c008 => TRIM(l_columns(8)),',
'                        p_c009 => TRIM(l_columns(9)),',
'                        p_c010 => TRIM(l_columns(10)),',
'',
'                        p_n001 => i',
'                    );',
'',
'                ELSE',
'                    raise_application_error(',
'                        -20003,',
'                        ''Line '' || i ||',
'                        '' contains '' || l_columns.COUNT ||',
'                        '' columns. Exactly 10 columns are required.''',
'                    );',
'                END IF;',
'',
'            END IF;',
'',
'        END LOOP;',
'    END IF;',
'',
'',
'    /*',
'      Retain upload information.',
'    */',
'    :P7_UPLOADED_FILENAME := l_filename;',
'',
'    IF l_row_count = 0 THEN',
'        raise_application_error(',
'            -20004,',
'            ''The uploaded TXT file contains no employee records.''',
'        );',
'    END IF;',
'',
'    /* Show preview after successful parsing */',
'    :P7_SHOW_PREVIEW := ''Y'';',
'',
'    /*',
'      Release temporary CLOB.',
'    */',
'    IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN',
'        DBMS_LOB.FREETEMPORARY(l_clob);',
'    END IF;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN',
'            DBMS_LOB.FREETEMPORARY(l_clob);',
'        END IF;',
'',
'        RAISE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(41937420234101642230)
,p_internal_uid=>42183650185079463812
,p_created_on=>wwv_flow_imp.dz('20260929070435Z')
,p_updated_on=>wwv_flow_imp.dz('20260929073039Z')
,p_created_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
,p_updated_by=>'ANUSHKADWIVEDI1308@GMAIL.COM'
);
end;
/
